import type { Env } from './env';
import { getDb } from './db';

// Data-access layer for the community domain, ported from
// backend/src/models/community.ts.
//
// Notes on the D1/SQLite port:
//  * node-postgres returned `rowCount`; the worker DbClient only returns rows,
//    so writes that report success/failure append `RETURNING id` and check rows.
//  * `col = ANY($1)` (uuid[]) becomes a JS-built IN (...) list.
//  * `GREATEST(x - 1, 0)` becomes a portable CASE expression.
//  * Ids are generated by SQLite defaults; invite codes use Web Crypto.

export type ReactionGroup = { emoji: string; count: number; user_ids: string[] };

// ── helpers ────────────────────────────────────────────────────────────────

async function affected(env: Env, sql: string, params: any[] = []): Promise<boolean> {
  const { rows } = await getDb(env).query<any>(sql, params);
  return rows.length > 0;
}

function placeholders(values: any[], startAt: number): string {
  return values.map((_v, i) => `$${startAt + i}`).join(', ');
}

function inviteCode(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(36).padStart(2, '0')).join('').slice(0, 26);
}

export function parseInterval(duration: string): number {
  const match = duration.match(/^(\d+)(m|h|d)$/);
  if (!match) return 3600000; // default 1h
  const n = parseInt(match[1], 10);
  switch (match[2]) {
    case 'm': return n * 60 * 1000;
    case 'h': return n * 3600 * 1000;
    case 'd': return n * 86400000;
    default: return 3600000;
  }
}

async function attachReactions(env: Env, messages: any[]): Promise<any[]> {
  if (messages.length === 0) return messages;
  const ids = messages.map((m) => m.id);
  const { rows: reactions } = await getDb(env).query<any>(
    `SELECT mr.message_id, mr.emoji, mr.user_id
     FROM message_reactions mr
     WHERE mr.message_id IN (${placeholders(ids, 1)})`,
    ids
  );

  const reactionMap = new Map<string, Map<string, { count: number; userIds: string[] }>>();
  for (const r of reactions) {
    if (!reactionMap.has(r.message_id)) reactionMap.set(r.message_id, new Map());
    const emojiMap = reactionMap.get(r.message_id)!;
    if (!emojiMap.has(r.emoji)) emojiMap.set(r.emoji, { count: 0, userIds: [] });
    const group = emojiMap.get(r.emoji)!;
    group.count++;
    group.userIds.push(r.user_id);
  }

  for (const msg of messages) {
    const emojiMap = reactionMap.get(msg.id);
    msg.reactions = emojiMap
      ? Array.from(emojiMap.entries()).map(([emoji, data]) => ({ emoji, count: data.count, user_ids: data.userIds }))
      : [];
  }
  return messages;
}

