export async function getReports(env: Env, status?: string): Promise<any[]> {
  let sql = `SELECT cr.*, u.name AS reporter_name
     FROM community_reports cr
     JOIN users u ON u.id = cr.reporter_id`;
  const params: any[] = [];

  if (status) {
    sql += ' WHERE cr.status = $1';
    params.push(status);
  }

  sql += ' ORDER BY cr.created_at DESC LIMIT 50';
  const { rows } = await getDb(env).query<any>(sql, params);
  return rows;
}

