// ── Moderation ─────────────────────────────────────────────────────────────

export async function createModerationAction(env: Env, input: {
  moderator_id: string;
  target_user_id: string;
  channel_id?: string;
  action: string;
  reason?: string;
  duration?: string;
}): Promise<void> {
  const db = getDb(env);
  let expiresAt = null;
  if (input.duration) {
    expiresAt = new Date(Date.now() + parseInterval(input.duration));
  }

  await db.query(
    `INSERT INTO community_moderation_actions (moderator_id, target_user_id, channel_id, action, reason, duration, expires_at)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [
      input.moderator_id,
      input.target_user_id,
      input.channel_id || null,
      input.action,
      input.reason || null,
      input.duration || null,
      expiresAt,
    ]
  );

  // Apply mute/ban
  if (input.channel_id && (input.action === 'mute' || input.action === 'ban')) {
    await db.query(
      'UPDATE channel_members SET is_muted = true WHERE channel_id = $1 AND user_id = $2',
      [input.channel_id, input.target_user_id]
    );
  }
  if (input.channel_id && (input.action === 'unmute' || input.action === 'unban')) {
    await db.query(
      'UPDATE channel_members SET is_muted = false WHERE channel_id = $1 AND user_id = $2',
      [input.channel_id, input.target_user_id]
    );
  }
}

// ── Invites ────────────────────────────────────────────────────────────────

export async function createInvite(env: Env, channelId: string, userId: string, maxUses?: number, expiresIn?: string): Promise<any> {
  const code = inviteCode();
  let expiresAt = null;
  if (expiresIn) {
    expiresAt = new Date(Date.now() + parseInterval(expiresIn));
  }

  const { rows } = await getDb(env).query<any>(
    `INSERT INTO channel_invites (channel_id, created_by, code, max_uses, expires_at)
     VALUES ($1, $2, $3, $4, $5)
     RETURNING *`,
    [channelId, userId, code, maxUses || null, expiresAt]
  );
  return rows[0];
}

export async function findInviteByCode(env: Env, code: string): Promise<any | null> {
  const { rows } = await getDb(env).query<any>(
    `SELECT * FROM channel_invites
     WHERE code = $1
       AND (max_uses IS NULL OR use_count < max_uses)
       AND (expires_at IS NULL OR expires_at > NOW())`,
    [code]
  );
  return rows[0] || null;
}

export async function useInvite(env: Env, code: string): Promise<boolean> {
  return affected(env, 'UPDATE channel_invites SET use_count = use_count + 1 WHERE code = $1 RETURNING id', [code]);
}

// ── Stats ──────────────────────────────────────────────────────────────────

export async function getChannelStats(env: Env, channelId: string): Promise<{ totalMessages: number; totalMembers: number; activeToday: number }> {
  const db = getDb(env);
  const msgCount = await db.query<any>(
    'SELECT COUNT(*) as count FROM channel_messages WHERE channel_id = $1 AND deleted = false',
    [channelId]
  );
  const memCount = await db.query<any>(
    'SELECT COUNT(*) as count FROM channel_members WHERE channel_id = $1',
    [channelId]
  );
  const activeCount = await db.query<any>(
    `SELECT COUNT(DISTINCT user_id) as count FROM channel_messages
     WHERE channel_id = $1 AND created_at > NOW() - INTERVAL '24 hours'`,
    [channelId]
  );

  return {
    totalMessages: parseInt(String(msgCount.rows[0]?.count ?? 0), 10),
    totalMembers: parseInt(String(memCount.rows[0]?.count ?? 0), 10),
    activeToday: parseInt(String(activeCount.rows[0]?.count ?? 0), 10),
  };
}

// ── Communities ────────────────────────────────────────────────────────────

export async function getCommunities(env: Env, userId: string): Promise<any[]> {
  const { rows } = await getDb(env).query<any>(
    `SELECT c.*,
       u.name AS creator_name, u.avatar AS creator_avatar,
       CASE WHEN cm.id IS NOT NULL THEN true ELSE false END AS is_member,
       COALESCE(cm.role, 'none') AS my_role,
       (SELECT r.status FROM community_join_requests r
        WHERE r.community_id = c.id AND r.user_id = $1
        ORDER BY r.created_at DESC LIMIT 1) AS my_request_status,
       (SELECT COUNT(*) FROM notifications n
        WHERE n.user_id = $1 AND n.read = false AND n.link LIKE '/community/' || c.id || '%') AS unread_count
     FROM communities c
     JOIN users u ON u.id = c.created_by
     LEFT JOIN community_members cm ON cm.community_id = c.id AND cm.user_id = $1
     WHERE c.is_archived = false
       AND (c.visibility = 'public' OR c.created_by = $1 OR cm.id IS NOT NULL
         OR EXISTS (SELECT 1 FROM community_join_requests r WHERE r.community_id = c.id AND r.user_id = $1))
     ORDER BY c.member_count DESC, c.created_at DESC`,
    [userId]
  );
  // SQLite returns 1/0 for the computed boolean; keep the Postgres shape.
  for (const row of rows) {
    row.is_member = !!row.is_member;
    row.unread_count = Number(row.unread_count) || 0;
  }
  return rows;
}

