export async function joinCommunity(env: Env, communityId: string, userId: string, role: string = 'member'): Promise<any> {
  const db = getDb(env);
  const { rows } = await db.query<any>(
    `INSERT INTO community_members (community_id, user_id, role)
     VALUES ($1, $2, $3)
     ON CONFLICT (community_id, user_id) DO NOTHING
     RETURNING *`,
    [communityId, userId, role]
  );
  if (!rows[0]) {
    const existing = await db.query<any>(
      'SELECT * FROM community_members WHERE community_id = $1 AND user_id = $2',
      [communityId, userId]
    );
    return existing.rows[0] || null;
  }
  await db.query(
    'UPDATE communities SET member_count = member_count + 1 WHERE id = $1',
    [communityId]
  );
  await db.query(
    'UPDATE community_channels SET member_count = member_count + 1 WHERE community_id = $1',
    [communityId]
  );
  return rows[0];
}

export async function leaveCommunity(env: Env, communityId: string, userId: string): Promise<boolean> {
  const left = await affected(
    env,
    'DELETE FROM community_members WHERE community_id = $1 AND user_id = $2 AND role != $3 RETURNING id',
    [communityId, userId, 'owner']
  );
  if (left) {
    await getDb(env).query(
      'UPDATE communities SET member_count = CASE WHEN member_count > 0 THEN member_count - 1 ELSE 0 END WHERE id = $1',
      [communityId]
    );
    await getDb(env).query(
      'UPDATE community_channels SET member_count = CASE WHEN member_count > 0 THEN member_count - 1 ELSE 0 END WHERE community_id = $1',
      [communityId]
    );
  }
  return left;
}

