export async function getCommunityStats(env: Env, communityId: string): Promise<{ memberCount: number; channelCount: number; activeToday: number }> {
  const db = getDb(env);
  const memCount = await db.query<any>(
    'SELECT COUNT(*) as count FROM community_members WHERE community_id = $1',
    [communityId]
  );
  const chanCount = await db.query<any>(
    'SELECT COUNT(*) as count FROM community_channels WHERE community_id = $1',
    [communityId]
  );
  const activeCount = await db.query<any>(
    `SELECT COUNT(DISTINCT cm.author_id) as count
     FROM channel_messages cm
     JOIN community_channels cc ON cc.id = cm.channel_id
     WHERE cc.community_id = $1 AND cm.created_at > NOW() - INTERVAL '24 hours'`,
    [communityId]
  );

  return {
    memberCount: parseInt(String(memCount.rows[0]?.count ?? 0), 10),
    channelCount: parseInt(String(chanCount.rows[0]?.count ?? 0), 10),
    activeToday: parseInt(String(activeCount.rows[0]?.count ?? 0), 10),
  };
}

export async function searchCommunities(env: Env, queryText: string): Promise<any[]> {
  const { rows } = await getDb(env).query<any>(
    `SELECT c.*, u.name AS creator_name, u.avatar AS creator_avatar
     FROM communities c
     JOIN users u ON u.id = c.created_by
     WHERE c.is_archived = false AND c.visibility = 'public'
       AND (c.name ILIKE $1 OR c.description ILIKE $1)
     ORDER BY c.member_count DESC
     LIMIT 20`,
    [`%${queryText}%`]
  );
  return rows;
}

